def transform(g):
    h,w=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    others=[c for c,_ in cnt.most_common() if c!=bg]
    anchor=others[0]; mk=others[-1]
    cells=[(r,j) for r in range(h) for j in range(w) if g[r][j]==anchor]
    rem=set(cells); segs=[]
    while rem:
        s=[rem.pop()]; seg=[]
        while s:
            r,j=s.pop(); seg.append((r,j))
            for nb in [(r+1,j),(r-1,j),(r,j+1),(r,j-1)]:
                if nb in rem: rem.remove(nb); s.append(nb)
        segs.append(seg)
    info=[]
    for seg in segs:
        rs=[a for a,b in seg]; js=[b for a,b in seg]
        info.append({'h':(max(rs)-min(rs))<(max(js)-min(js)),'r0':min(rs),'r1':max(rs),'c0':min(js),'c1':max(js)})
    if info[0]['h']: info.sort(key=lambda t:t['r0'])
    else: info.sort(key=lambda t:t['c0'])
    A,B=info[0],info[1]
    out=[r[:] for r in g]
    for r in range(h):
        for j in range(w):
            if g[r][j]!=mk: continue
            if A['h']:
                if A['c0']<=j<=A['c1']: src,dst,off=A,B,j-A['c0']
                else: src,dst,off=B,A,j-B['c0']
            else:
                if A['r0']<=r<=A['r1']: src,dst,off=A,B,r-A['r0']
                else: src,dst,off=B,A,r-B['r0']
            if src['h']:
                st=1 if r>src['r0'] else -1
                for rr in range(src['r0']+st,r,st): out[rr][j]=mk
            else:
                st=1 if j>src['c0'] else -1
                for jj in range(src['c0']+st,j,st): out[r][jj]=mk
            out[r][j]=4
            # full projection on dst from its start offset
            if dst['h']:
                pj=dst['c0']+off
                lo,hi=min(src['r0'],dst['r0']),max(src['r0'],dst['r0'])
                for rr in range(lo,hi):
                    if g[rr][pj]!=anchor: out[rr][pj]=mk
            else:
                pr=dst['r0']+off
                lo,hi=min(src['c0'],dst['c0']),max(src['c0'],dst['c0'])
                for jj in range(lo,hi):
                    if g[pr][jj]!=anchor: out[pr][jj]=mk
    return out
